body.script:
// Données structurées : identité du site (schema.org)
if (window.LeLaboSEO) {
  LeLaboSEO.jsonld({
    '@context': 'https://schema.org', '@type': 'Organization',
    name: 'Le Labo', url: LeLaboSEO.BASE,
    logo: LeLaboSEO.BASE + '/assets/img/logo-cat.svg',
    description: "Plateforme pédagogique de tutoriels web et design : WordPress, Canva et Illustrator, avec quiz et cartes à collectionner."
  });
  LeLaboSEO.jsonld({
    '@context': 'https://schema.org', '@type': 'WebSite',
    name: 'Le Labo', url: LeLaboSEO.BASE, inLanguage: 'fr',
    potentialAction: {
      '@type': 'SearchAction',
      target: LeLaboSEO.BASE + '/tutos.html?q={search_term_string}',
      'query-input': 'required name=search_term_string'
    }
  });
}
